const body = $json.body || {};
const action = body.action || 'event';
const sender = body.sender?.login || 'guitarist';
const repo = body.repository?.full_name || 'merx666/gryf-guitar';
const stars = body.repository?.stargazers_count || 0;

let message = '';
let shouldTweet = false;
let tweetText = '';

if (action === 'published' && body.release) {
  const tag = body.release.tag_name || 'Update';
  tweetText = `🎸 NEW RELEASE: Gryf ${tag} is live!\n\nAuthentic Rocksmith 3D note highway, real-time pitch detection & in-browser amp DSP.\n\nPlay free: http://92.118.206.90:3000\nGitHub: https://github.com/merx666/gryf-guitar\n#Guitar #Rocksmith #OpenSource`;
  shouldTweet = true;
  message = `🚀 Release ${tag} announced!`;
} else if (action === 'created' && body.starred_at) {
  message = `⭐ New Star on GitHub! ${sender} just starred ${repo}. Total stars: ${stars}`;
  if (stars > 0 && stars % 25 === 0) {
    tweetText = `🎉 Gryf just crossed ${stars} stars on GitHub!\n\nThank you to every guitarist testing our open-source browser-based rhythm trainer: http://92.118.206.90:3000\n#OpenSource #Guitar`;
    shouldTweet = true;
  }
} else {
  message = `🔔 GitHub Event: ${action} by ${sender} on ${repo}`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    event: action,
    sender,
    stars,
    message,
    shouldTweet,
    tweetText
  }
}];

const execution = $json.execution || {};
return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow: 'GitHub Growth Tracker',
    error: execution.error?.message || 'Error occurred'
  }
}];
